window.SHB_DATA = [{"id":"s1t1","title":"Übung 1 · Teil 1","thema":"Bewerbung","type":"bank","head":"Betreff: Meine Bewerbung vom 3. März","paras":["Sehr geehrte Frau Hoffmann,","herzlichen Dank für Ihre Eingangsbestätigung vom 6. März.","Mir ist natürlich klar, dass die Auswahl der passenden Kandidaten Zeit braucht. {46} würde ich gerne erfahren, wie der aktuelle Stand meiner Bewerbung ist.","Könnten Sie mir bitte kurz mitteilen, {47} Sie meine Unterlagen {48} prüfen konnten?","An der Stelle als Sachbearbeiter im Einkauf bin ich nach wie vor sehr interessiert.","Da ich {49} drei Wochen einen Kurs zum Thema SAP abgeschlossen habe, sende ich Ihnen anbei das Zertifikat.","Falls Ihnen noch Unterlagen fehlen, reiche ich diese gerne {50} nach. {51} meiner Erfahrung im Einkauf bin ich überzeugt, dass ich gut in Ihr Team passe.","Ich freue mich auf ein persönliches Gespräch.","Mit freundlichen Grüßen<br>Mykola Bondar"],"bank":[["a","wann"],["b","deswegen"],["c","aufgrund"],["d","außerdem"],["e","inzwischen"],["f","dennoch"],["g","daher"],["h","vor"],["i","sofort"],["j","ob"]],"key":{"46":"f","47":"j","48":"e","49":"h","50":"i","51":"c"},"cap":[46,51],"topic":{"46":"Konnektor","47":"Konnektor","48":"Adverb","49":"Präposition","50":"Adverb","51":"Präposition"},"why":{"46":"dennoch — «тем не менее»: понимаю, что нужно время, и всё же спрашиваю. Это уступка. daher и deswegen («поэтому») дали бы причину — по смыслу не подходит.","47":"ob — косвенный вопрос «ли»: проверили ли уже документы. wann спрашивает «когда».","48":"inzwischen — «уже, к этому моменту».","49":"vor + Dat. — «назад»: vor drei Wochen — три недели назад.","50":"sofort nachreichen — сразу дослать документы.","51":"aufgrund + Gen. — «на основании, благодаря»: aufgrund meiner Erfahrung."},"extra":"Лишние: wann, deswegen, daher, außerdem."},{"id":"s1t2","title":"Übung 1 · Teil 2","thema":"Auftragsbestätigung","type":"abc","head":"Auftragsbestätigung","paras":["Sehr geehrte Frau Krüger,","vielen Dank für Ihre Bestellung vom 14.05.20xx, die Sie uns über unser Online-Portal geschickt haben. Nachfolgend bestätigen wir die bestellten Artikel auf Grundlage {52}.","<div class=\"shb-tw\"><table class=\"shb-t\"><tr><th>Pos.</th><th>Menge</th><th>Artikel</th><th>Einzelpreis</th><th>Gesamtpreis</th></tr><tr><td>1</td><td>40</td><td>Bürostuhl „Ergo Plus“</td><td>249,00</td><td>9.960,00 Euro</td></tr><tr><td>2</td><td>40</td><td>Schreibtischlampe LED</td><td>39,00</td><td>1.560,00 Euro</td></tr><tr><td></td><td></td><td></td><td>Summe netto</td><td>11.520,00 Euro</td></tr><tr><td></td><td></td><td></td><td>19 % MwSt.</td><td>2.188,80 Euro</td></tr><tr><td></td><td></td><td></td><td>Gesamtbetrag</td><td>13.708,80 Euro</td></tr></table></div>","Wir garantieren Ihnen eine {53} und freuen uns auf {54}! Die Lieferung erfolgt in der KW 22.","Bei {55} der Lieferung wenden Sie sich bitte an Herrn Petersen, der Ihnen unter der Nummer 0711 4567-23 {56} steht. Wir bitten Sie {57} und Rücksendung dieser Auftragsbestätigung bis zum 20.05.20xx.","Mit freundlichen Grüßen<br>Lena Brandt"],"items":[{"n":52,"o":["unserem Angebot","unserer Bestellung","unseres Angebots"],"a":2,"t":"Präposition","w":"auf Grundlage + Gen. — «на основании»: auf Grundlage unseres Angebots. Нужен Genitiv, поэтому не unserem; заказ (Bestellung) делает клиент, а не продавец."},{"n":53,"o":["sorgfältige Abwicklung","vielfältige Aufgabe","günstige Kündigung"],"a":0,"t":"Wortschatz","w":"eine sorgfältige Abwicklung garantieren — гарантировать тщательное выполнение заказа."},{"n":54,"o":["einen langen Urlaub","eine gute Zusammenarbeit","eine schwierige Aufgabe"],"a":1,"t":"Wortschatz","w":"sich freuen auf eine gute Zusammenarbeit — стандартная концовка делового письма."},{"n":55,"o":["Antworten im Laufe","Fragen im Zuge","Wünschen trotz"],"a":1,"t":"Präposition","w":"im Zuge + Gen. — «в ходе»: Fragen im Zuge der Lieferung — вопросы в ходе поставки."},{"n":56,"o":["gerne zur Beratung","gerne zur Diskussion","gerne zur Verfügung"],"a":2,"t":"Nomen-Verb-Verbindung","w":"jdm. gerne zur Verfügung stehen — охотно быть в распоряжении."},{"n":57,"o":["um Unterzeichnung","um Unterstützung","um Untersuchung"],"a":0,"t":"Rektion","w":"jdn. um etw. bitten — просить о чём-то: um Unterzeichnung und Rücksendung — подписать и вернуть."}]},{"id":"s2t1","title":"Übung 2 · Teil 1","thema":"Kündigung (Ausbildung)","type":"bank","head":"Kündigung Ihres Ausbildungsvertrages","paras":["Sehr geehrter Herr Yilmaz,","hiermit kündigen wir den am 01.09.20xx mit Ihnen geschlossenen Ausbildungsvertrag zum Fachlageristen.","Zur Begründung:","{46} von Ihnen unterschriebene Ausbildungsvertrag {47} in § 6 die Vereinbarung, dass Sie Ihre Arbeit um 7:00 Uhr beginnen. {48} sind Sie am 12.10. erst um 7:25 Uhr im Lager erschienen. Am 19.10. kamen Sie {49} um 7:40 Uhr. Auch am 02.11. haben Sie Ihre Schicht verspätet angetreten.","In unserem Gespräch am 05.11., an dem auch die Ausbildungsleiterin Frau Kraus teilgenommen hat, konnten Sie für Ihre Verspätungen keine Erklärung geben. Am 09.11. sind Sie erneut zu spät gekommen.","Da wir {50} unserer Lieferzeiten auf ein pünktliches Erscheinen aller Mitarbeiter angewiesen sind, beanstanden wir Ihr Verhalten {51} ausdrücklich.","Aus den genannten Gründen endet das Ausbildungsverhältnis zum 31.12.20xx.","Mit freundlichen Grüßen<br>Sabine Lorenz<br>Personalabteilung"],"bank":[["a","trotz"],["b","dem"],["c","der"],["d","erst"],["e","gleichwohl"],["f","enthält"],["g","obwohl"],["h","aufgrund"],["i","bekommt"],["j","hiermit"]],"key":{"46":"c","47":"f","48":"e","49":"d","50":"h","51":"j"},"cap":[46,48],"topic":{"46":"Deklination","47":"Wortschatz","48":"Konnektor","49":"Adverb","50":"Präposition","51":"Adverb"},"why":{"46":"der — Nominativ: договор здесь подлежащее. Подсказка — окончание unterschriebene: после dem было бы unterschriebenen.","47":"enthält — «содержит»: der Vertrag enthält eine Vereinbarung. bekommt по смыслу не подходит.","48":"gleichwohl — «тем не менее» (= trotzdem): договорённость есть, а вы всё равно опоздали. trotz — предлог, ему нужно существительное; obwohl — союз, глагол ушёл бы в конец.","49":"erst — «только, не раньше»: erst um 7:40 Uhr — то есть с опозданием.","50":"aufgrund + Gen. — «из-за, в силу»: aufgrund unserer Lieferzeiten.","51":"hiermit — «настоящим»: официальная формула beanstanden wir hiermit ausdrücklich."},"extra":"Лишние: trotz, dem, obwohl, bekommt."},{"id":"s2t2","title":"Übung 2 · Teil 2","thema":"Auftragsbestätigung","type":"abc","head":"Auftragsbestätigung","paras":["Sehr geehrter Herr Wagner,","herzlichen Dank für {52} vom 03.03.20xx, den wir Ihnen hiermit gerne bestätigen.","Die technischen Details der Drucker entnehmen Sie bitte Seite 4 {53} vom 20.02.20xx.","{54} eines Liefertermins wird sich unser Kundenservice in der KW 12 telefonisch bei Ihnen melden.","Die Geräte werden spätestens am 31.03.20xx an Ihre Filiale in Stuttgart, Königstraße 15, geliefert.","Wir bedanken uns herzlich für {55} und Ihren Auftrag und freuen uns auf eine {56} mit Ihrem Unternehmen.","Bei Rückfragen steht Ihnen Frau Melanie Schulz montags bis freitags von 8:00 bis 16:00 Uhr gerne {57}.","Mit freundlichen Grüßen<br>Tobias Keller"],"items":[{"n":52,"o":["unseren Auftrag","Ihren Auftrag","Ihre Anfrage"],"a":1,"t":"Wortschatz","w":"Ihren Auftrag — заказ сделал клиент, мы его подтверждаем. «den» указывает на мужской род (der Auftrag); у Anfrage было бы «die»."},{"n":53,"o":["unserer Bestellung","unserer Abwicklung","unseres Angebots"],"a":2,"t":"Wortschatz","w":"unseres Angebots — Genitiv: страница 4 нашего предложения. Заказывал клиент, поэтому не «unserer Bestellung»."},{"n":54,"o":["Zwecks Vereinbarung","Mangels Interesse","Aufgrund von"],"a":0,"t":"Präposition","w":"zwecks + Gen. — «с целью»: zwecks Vereinbarung eines Liefertermins — чтобы согласовать дату поставки. mangels — «из-за отсутствия»."},{"n":55,"o":["Ihre Lieferung","Ihre Beschwerde","Ihr Vertrauen"],"a":2,"t":"Wortschatz","w":"für Ihr Vertrauen — стандартная благодарность клиенту."},{"n":56,"o":["gute Zusammenarbeit","lange Pause","fröhliche Feier"],"a":0,"t":"Wortschatz","w":"auf eine gute Zusammenarbeit — стандартная концовка делового письма."},{"n":57,"o":["zur Bearbeitung","zur Verfügung","zur Aufnahme"],"a":1,"t":"Nomen-Verb-Verbindung","w":"jdm. zur Verfügung stehen — быть в распоряжении."}]},{"id":"s3t1","title":"Übung 3 · Teil 1","thema":"Kündigung","type":"bank","head":"Meine Kündigung zum 30.06.20xx","paras":["Sehr geehrter Herr Neumann,","wie Ihnen bekannt ist, habe ich mein Arbeitsverhältnis fristgerecht zum 30.06.20xx gekündigt, da ich mit meiner Familie nach Hamburg umziehe. {46} heute habe ich mein Arbeitszeugnis leider nicht erhalten.","Ich möchte betonen, {47} ein qualifiziertes Zeugnis für meine Bewerbungen sehr wichtig ist. Ich habe nicht nur sieben Jahre als Buchhalterin in Ihrem Unternehmen gearbeitet, {48} auch mehrere Schulungen zum Thema DATEV besucht. Bitte bestätigen Sie im Zeugnis auch meine Teilnahme {49} diesen Schulungen.","Außerdem möchte ich mich {50} bedanken, dass ich in Ihrem Team so viel lernen durfte. Ich blicke gerne {51} zurück.","Ich danke Ihnen im Voraus für Ihre Mühe.","Mit freundlichen Grüßen<br>Anna Petrenko"],"bank":[["a","darauf"],["b","dafür"],["c","bis"],["d","seit"],["e","dass"],["f","vor"],["g","sondern"],["h","obwohl"],["i","auf"],["j","an"]],"key":{"46":"c","47":"e","48":"g","49":"j","50":"b","51":"a"},"cap":[46],"topic":{"46":"Präposition","47":"Konnektor","48":"Konnektor","49":"Rektion","50":"da-Wort","51":"da-Wort"},"why":{"46":"bis heute — «до сих пор». seit heute — «с сегодняшнего дня», по смыслу не подходит.","47":"dass — придаточное после betonen: «подчеркнуть, что…».","48":"nicht nur …, sondern auch — «не только…, но и».","49":"die Teilnahme an + Dat. — участие в чём-то: Teilnahme an diesen Schulungen.","50":"sich dafür bedanken, dass … — da-Wort заранее указывает на придаточное с dass: sich bedanken für → dafür.","51":"zurückblicken auf + Akk. → darauf: «с удовольствием вспоминаю об этом». Просто auf без объекта нельзя."},"extra":"Лишние: seit, vor, obwohl, auf."},{"id":"s3t2","title":"Übung 3 · Teil 2","thema":"Anfrage","type":"abc","head":"Anfrage Online-Sprachkurse","paras":["Sehr geehrte Frau Dr. Weber,","wir sind ein {52} für Logistikdienstleistungen in Süddeutschland. Auf der Messe „Personal Süd“ in Stuttgart sind wir auf Ihr {53} im Bereich der Online-Sprachkurse aufmerksam geworden.","Besonders interessiert uns Ihr Kurs „Deutsch im Beruf B2“. Wir möchten Sie daher um ein Beratungsgespräch bitten, in dem unsere Personalabteilung über den Kurs ausführlich informiert wird. Außerdem benötigen wir eine {54} aller Kosten, falls wir den Kurs für unsere Mitarbeiter buchen.","Eine Übersicht, aus der hervorgeht, {55} Sie Gruppenrabatte gewähren, wäre für uns ebenfalls interessant.","Wir haben insgesamt 85 Mitarbeiter an drei Standorten. Falls Sie noch Fragen {56} haben, bitten wir Sie, mit unserem Personalleiter, Herrn Jan Koch, {57}. Er beantwortet Ihre Fragen gerne.","Wir freuen uns auf Ihre Antwort.","Mit freundlichen Grüßen<br>Petra Schmid"],"items":[{"n":52,"o":["führender Anbieter","bekannte Unternehmen","große Firma"],"a":0,"t":"Deklination","w":"ein führender Anbieter — «ведущий поставщик». ein + мужской род → окончание -er. Unternehmen — средний род (ein bekanntes), Firma — женский (eine)."},{"n":53,"o":["vielfältige Kurse","breites Angebot","großes Interesse"],"a":1,"t":"Wortschatz","w":"auf Ihr breites Angebot aufmerksam werden — обратить внимание на ваш широкий выбор. Kurse — мн. ч., было бы Ihre; Interesse по смыслу не подходит."},{"n":54,"o":["kurze Mitteilung","bezahlte Rechnung","detaillierte Aufstellung"],"a":2,"t":"Wortschatz","w":"eine detaillierte Aufstellung aller Kosten — подробный перечень всех расходов."},{"n":55,"o":["mit welchen Mitteln","unter welchen Bedingungen","laut welchem Gesetz"],"a":1,"t":"Wortschatz","w":"unter welchen Bedingungen — «на каких условиях» вы даёте скидки группам."},{"n":56,"o":["bezüglich unserer Anfrage","infolge unserer Bestellung","trotz unserer Anfrage"],"a":0,"t":"Präposition","w":"bezüglich + Gen. — «касательно»: Fragen bezüglich unserer Anfrage. infolge — «вследствие», а заказа ещё нет."},{"n":57,"o":["telefonisch zu verhandeln","mitzuteilen","Kontakt aufzunehmen"],"a":2,"t":"Nomen-Verb-Verbindung","w":"mit jdm. Kontakt aufnehmen — связаться с кем-то."}]},{"id":"s4t1","title":"Übung 4 · Teil 1","thema":"Bewerbung / Nachfrage","type":"bank","head":"Betreff: Meine Bewerbung vom 10.09.20xx","paras":["Sehr geehrte Damen und Herren,","vielen Dank für Ihre freundliche E-Mail vom 12.09.20xx. {46} sind seit dem Ende der Bewerbungsfrist drei Wochen vergangen. {47} möchte ich mich erkundigen, wie das Auswahlverfahren weitergeht.","Ich interessiere mich nach wie vor sehr für die Stelle als Berufskraftfahrer in Ihrer Spedition und würde mich über eine positive Antwort freuen.","Da ich {48} noch ein Angebot von einer anderen Firma bekommen habe, wäre es hilfreich, wenn Sie mir mitteilen könnten, {49} ich spätestens mit einer Entscheidung rechnen kann. {50} des kurzen Arbeitswegs würde ich aber lieber bei Ihnen arbeiten.","Für Fragen {51} meinem Lebenslauf erreichen Sie mich jederzeit per E-Mail oder unter 0176 1234567.","Vielen Dank für Ihre Mühe.","Mit freundlichen Grüßen<br>Oleksandr Melnyk"],"bank":[["a","inzwischen"],["b","daher"],["c","ob"],["d","wann"],["e","auch"],["f","über"],["g","trotz"],["h","aufgrund"],["i","da"],["j","zu"]],"key":{"46":"a","47":"b","48":"e","49":"d","50":"h","51":"j"},"cap":[46,47,50],"topic":{"46":"Adverb","47":"Konnektor","48":"Adverb","49":"Konnektor","50":"Präposition","51":"Rektion"},"why":{"46":"inzwischen — «тем временем, уже»: прошло уже три недели.","47":"daher — «поэтому»: прошло три недели → поэтому спрашиваю. Сравни с Übung 1: там «понимаю, что нужно время» → dennoch (уступка).","48":"auch noch — «ещё и, вдобавок»: получил предложение ещё и от другой фирмы.","49":"wann — косвенный вопрос о времени: wann ich spätestens … rechnen kann. ob не сочетается со spätestens.","50":"aufgrund + Gen. — «из-за, благодаря»: aufgrund des kurzen Arbeitswegs. trotz дал бы противоречие.","51":"Fragen zu + Dat. — вопросы по чему-то: zu meinem Lebenslauf. Подсказка — meinem (Dativ); über требовал бы Akk.: meinen."},"extra":"Лишние: ob, über, trotz, da."},{"id":"s4t2","title":"Übung 4 · Teil 2","thema":"Auftragserteilung","type":"abc","head":"Auftragserteilung","paras":["Sehr geehrter Herr Fischer,","wir danken Ihnen für das informative Gespräch am 05.05.20xx, in dem Sie uns {52} noch einmal ausführlich vorgestellt haben.","Wir sind ein Hotel mit 120 Zimmern in der Innenstadt von Freiburg und möchten unseren Frühstücksraum modernisieren. Deshalb möchten wir unseren {53} erweitern.","Ihre Kaffeemaschinen haben uns nicht nur technisch überzeugt, sondern uns auch dazu veranlasst, die bereits {54} zu erhöhen.","Gemäß Ihrem Angebot vom 20.04. bestellen wir:<br>4 Kaffeevollautomaten „Barista Pro“<br>8 Milchkühler „Fresh“<br>2 Wartungspakete für 24 Monate","Wir erwarten die Lieferung bis zum 15.06. Wie vereinbart, sind alle {55} Nettopreise. Bitte schicken Sie uns eine {56}.","Wenn die Lieferung zu unserer Zufriedenheit erfolgt, können Sie {57}.","Mit freundlichen Grüßen<br>Markus Engel"],"items":[{"n":52,"o":["Ihre Anfrage","Ihre Angaben","Ihr Angebot"],"a":2,"t":"Wortschatz","w":"Ihr Angebot — на встрече поставщик представил своё предложение; ниже: Gemäß Ihrem Angebot. Запрос (Anfrage) делает покупатель."},{"n":53,"o":["neue Bestellung","letzten Auftrag","vorherige Lieferung"],"a":1,"t":"Deklination","w":"unseren letzten Auftrag — unseren = Akk. мужского рода → der Auftrag. Bestellung и Lieferung — женского рода, было бы unsere."},{"n":54,"o":["bestellte Menge","geplante Auslieferung","besprochene Einlieferung"],"a":0,"t":"Wortschatz","w":"die bereits bestellte Menge erhöhen — увеличить уже заказанное количество."},{"n":55,"o":["genannten Preise","bezahlten Rechnungen","gesendeten Kalkulationen"],"a":0,"t":"Wortschatz","w":"alle genannten Preise sind Nettopreise — все названные цены указаны без НДС."},{"n":56,"o":["prompte Bearbeitung","zuverlässige Ausführung","kurze Auftragsbestätigung"],"a":2,"t":"Wortschatz","w":"eine kurze Auftragsbestätigung schicken — прислать подтверждение заказа. «Обработку» (Bearbeitung) прислать нельзя."},{"n":57,"o":["auf weitere Rabatte verzichten","mit weiteren Aufträgen rechnen","die Bestellung stornieren"],"a":1,"t":"Rektion","w":"mit weiteren Aufträgen rechnen — «можете рассчитывать на новые заказы»; rechnen mit + Dat."}]},{"id":"s5t1","title":"Übung 5 · Teil 1","thema":"Bewerbung","type":"bank","head":"Meine Bewerbung als Verkäufer im Elektronikmarkt","paras":["Sehr geehrte Frau Albrecht,","{46} drei Jahren im Kundenservice möchte ich mich beruflich weiterentwickeln. Ihre Stellenanzeige hat mich sofort angesprochen, denn ich erfülle alle Voraussetzungen {47}. Ich bin sicher, dass ich Ihr Team gut verstärken kann.","Für mich steht der Kunde im Mittelpunkt. Ich möchte, dass jeder Kunde {48} das Richtige für sich findet. Deshalb empfehle ich {49} Produkte, die ich selbst getestet habe. Und was gibt es Schöneres {50} einen zufriedenen Kunden, der gerne wiederkommt?","Ich suche eine langfristige Stelle. Arbeit am Wochenende ist für mich kein Problem. Ich könnte ab dem 01.03.20xx bei Ihnen anfangen.","{51} beantworte ich Ihre Fragen in einem persönlichen Gespräch.","Mit freundlichen Grüßen<br>Dmytro Koval"],"bank":[["a","nur"],["b","gern"],["c","sowie"],["d","für"],["e","nach"],["f","ob"],["g","als"],["h","dafür"],["i","in"],["j","genau"]],"key":{"46":"e","47":"h","48":"j","49":"a","50":"g","51":"b"},"cap":[51],"topic":{"46":"Präposition","47":"da-Wort","48":"Adverb","49":"Adverb","50":"Konnektor","51":"Adverb"},"why":{"46":"nach + Dat. — «после»: nach drei Jahren — после трёх лет. in drei Jahren означало бы «через три года».","47":"die Voraussetzungen dafür erfüllen — соответствовать требованиям (для этой работы): dafür = «для этого».","48":"genau das Richtige — «именно то, что нужно». Устойчивое выражение.","49":"nur — «только»: рекомендую только то, что проверил сам.","50":"Schöneres … als — сравнение: «что может быть лучше, чем…». После сравнительной степени — als.","51":"Gern beantworte ich Ihre Fragen — «охотно отвечу», вежливая концовка письма."},"extra":"Лишние: sowie, für, ob, in."},{"id":"s5t2","title":"Übung 5 · Teil 2","thema":"Angebot","type":"abc","head":"Ihre Anfrage","paras":["Sehr geehrter Herr Lehmann,","vielen Dank für das angenehme Telefongespräch und Ihre Anfrage. Wie besprochen, finden Sie im Anhang {52} zu unserer Buchhaltungssoftware „KontoKlar“ für kleine und mittlere Unternehmen.","Als erfahrener Anbieter für den {53} in der Buchhaltung bieten wir Ihnen eine einfache Lösung für Rechnungen, Belege und die Steuererklärung.","Gerne können wir Ihnen die Software 30 Tage lang kostenlos {54}. Danach gilt eine {55}.","Wenn Sie einen {56} möchten, wenden Sie sich bitte an Frau Yildiz, denn sie ist für Verträge zuständig.","Wir freuen uns auf {57} und hoffen, Sie bald zu unseren zufriedenen Kunden zählen zu dürfen.","Mit freundlichen Grüßen<br>Jonas Roth"],"items":[{"n":52,"o":["unsere aktuelle Rechnung","unser aktuelles Angebot","Ihre aktuelle Bestellung"],"a":1,"t":"Wortschatz","w":"unser aktuelles Angebot — в приложении наше предложение. Счёта (Rechnung) ещё нет, а заказ (Bestellung) делает клиент."},{"n":53,"o":["professionellen Einsatz","internationalen Handel","privaten Urlaub"],"a":0,"t":"Wortschatz","w":"für den professionellen Einsatz — «для профессионального использования»."},{"n":54,"o":["in Rechnung stellen","in Auftrag geben","zur Verfügung stellen"],"a":2,"t":"Nomen-Verb-Verbindung","w":"kostenlos zur Verfügung stellen — предоставить бесплатно. in Rechnung stellen — выставить счёт, это противоречит kostenlos."},{"n":55,"o":["interne Absprache","freundliche Beratung","monatliche Kündigungsfrist"],"a":2,"t":"Wortschatz","w":"eine monatliche Kündigungsfrist — срок расторжения — один месяц."},{"n":56,"o":["Telefongespräch führen","Jahresvertrag abschließen","wichtiges Angebot machen"],"a":1,"t":"Deklination","w":"einen Jahresvertrag abschließen — заключить годовой договор; за договоры отвечает Frau Yildiz. Telefongespräch и Angebot — среднего рода: было бы ein, а не einen."},{"n":57,"o":["Ihre Bestellung","Ihre Anfrage","unser Angebot"],"a":0,"t":"Wortschatz","w":"sich freuen auf Ihre Bestellung — «будем рады вашему заказу». Запрос уже был, а предложение делает сама фирма."}]},{"id":"s6t1","title":"Übung 6 · Teil 1","thema":"Ausbildung","type":"bank","head":"","paras":["Sehr geehrter Herr Brenner,","nach unserem netten Telefonat bin ich noch motivierter als {46}, bei Ihnen die Ausbildung zur Kauffrau für Spedition und Logistikdienstleistung zu beginnen.","Eine lange Einarbeitung ist bei mir nicht nötig, weil ich Ihre Firma {47} kenne. {48} meines Praktikums in Ihrer Disposition (vom 01.04. bis 31.05.20xx) habe ich Transporte geplant und Frachtpapiere vorbereitet. Mein damaliger Betreuer, Herr Vogel, wird Ihnen {49} bestätigen, dass ich zuverlässig gearbeitet habe. Meine Erfahrungen aus dem Praktikum {50} meine guten Englischkenntnisse möchte ich in Ihrem Team einsetzen.","In einem persönlichen Gespräch würde ich Sie gerne {51} überzeugen, dass ich die richtige Auszubildende für Ihr Unternehmen bin.","Mit freundlichen Grüßen<br>Iryna Shevchenko"],"bank":[["a","während"],["b","davon"],["c","weshalb"],["d","würden"],["e","gern"],["f","bereits"],["g","sowie"],["h","seit"],["i","zuvor"],["j","das"]],"key":{"46":"i","47":"f","48":"a","49":"e","50":"g","51":"b"},"cap":[48],"topic":{"46":"Adverb","47":"Adverb","48":"Präposition","49":"Adverb","50":"Konnektor","51":"da-Wort"},"why":{"46":"als zuvor — «чем раньше»: noch motivierter als zuvor — мотивирована ещё больше, чем до разговора.","47":"bereits — «уже»: я уже знаю вашу фирму (по практике).","48":"während + Gen. — «во время»: während meines Praktikums.","49":"gern bestätigen — «охотно подтвердит».","50":"sowie — «а также»: соединяет два подлежащих — Erfahrungen sowie Englischkenntnisse.","51":"jdn. davon überzeugen, dass … — da-Wort указывает на придаточное с dass: überzeugen von → davon."},"extra":"Лишние: weshalb, würden, seit, das."},{"id":"s6t2","title":"Übung 6 · Teil 2","thema":"Auftragserteilung","type":"abc","head":"Auftragserteilung: Dachsanierung Lindenweg 8, Calw","paras":["Sehr geehrte Damen und Herren,","hiermit bestätigen wir den bereits am 12.03.20xx telefonisch {52} gemäß {53} vom 28.02.20xx für die Sanierung des Daches, wie dort beschrieben.","Die Auftragssumme beträgt nach Prüfung 86.400 Euro zuzüglich der {54} in Höhe von 19 %. Das vereinbarte Skonto von 2 % gilt bei Zahlung innerhalb von 10 Tagen.","Die Preise des Angebots sind Festpreise. In unseren Gesprächen haben wir {55} Folgendes vereinbart:","1. Die Arbeiten beginnen am 02.05.20xx.<br>2. Die Arbeiten sind bis zum 30.06.20xx abzuschließen.<br>3. Sie stellen uns eine Gewährleistungsbürgschaft in Höhe von 5 % der Auftragssumme.","Wenn Sie noch Fragen {56} haben, rufen Sie mich gerne an. Wir freuen uns auf eine {57}.","Mit freundlichen Grüßen<br>Klaus Bauer"],"items":[{"n":52,"o":["neues Angebot","ausführliche Beratung","erteilten Auftrag"],"a":2,"t":"Deklination","w":"den … erteilten Auftrag — подтверждаем заказ, уже выданный по телефону. den требует мужского рода (der Auftrag)."},{"n":53,"o":["Ihrem Angebot","Ihrer Bestellung","Ihres Interesses"],"a":0,"t":"Präposition","w":"gemäß + Dat. — «согласно»: gemäß Ihrem Angebot. Предложение делал подрядчик, заказ выдаёт заказчик — автор письма."},{"n":54,"o":["möglichen Versandkosten","gesetzlichen Mehrwertsteuer","geplanten Rabatte"],"a":1,"t":"Wortschatz","w":"zuzüglich der gesetzlichen Mehrwertsteuer — «плюс НДС по закону». 19 % — это ставка НДС."},{"n":55,"o":["laut Anspruch","zusätzlich","nach Bedarf"],"a":1,"t":"Adverb","w":"zusätzlich — «дополнительно»: кроме цен договорились ещё о трёх пунктах."},{"n":56,"o":["statt der Auftragsaufhebung","in Bezug auf den Urlaub","bezüglich der Auftragserteilung"],"a":2,"t":"Präposition","w":"bezüglich + Gen. — «касательно»: Fragen bezüglich der Auftragserteilung."},{"n":57,"o":["gute Zusammenarbeit","schnelle Kündigung","unverbindliches Angebot"],"a":0,"t":"Wortschatz","w":"sich freuen auf eine gute Zusammenarbeit — стандартная концовка письма."}],"extra":"Полезные слова: der/das Skonto — скидка за быструю оплату; die Gewährleistungsbürgschaft — гарантия на устранение дефектов."},{"id":"s7t1","title":"Übung 7 · Teil 1","thema":"Kündigung","type":"bank","head":"Kündigung zum 31.03.20xx","paras":["Sehr geehrte Frau Schäfer,","wie Sie ja {46} wissen, arbeite ich seit 2019 als Sachbearbeiter in Ihrer Versicherungsagentur. {47} meinen Umzug nach Bremen bedingt, muss ich mein Arbeitsverhältnis leider fristgerecht zum 31.03.20xx kündigen.","Da ich den Nachweis für meinen neuen Mietvertrag brauche, bestätigen Sie mir bitte {48} schriftlich den Eingang dieser Kündigung.","Außerdem bitte ich Sie {49} ein qualifiziertes Arbeitszeugnis bis zum 15.03.20xx, da ich es bei meinem neuen Arbeitgeber vorlegen muss.","Ich möchte mich bei Ihnen {50} herzlich bedanken. Ich konnte mich in Ihrem Team nicht nur fachlich weiterentwickeln, {51} habe auch viele nette Kolleginnen und Kollegen kennengelernt.","Bei Rückfragen erreichen Sie mich jederzeit.","Mit freundlichen Grüßen<br>Viktor Hrytsenko"],"bank":[["a","sicherlich"],["b","keineswegs"],["c","pro"],["d","umgehend"],["e","nochmals"],["f","kaum"],["g","das"],["h","sondern"],["i","um"],["j","durch"]],"key":{"46":"a","47":"j","48":"d","49":"i","50":"e","51":"h"},"cap":[47],"topic":{"46":"Adverb","47":"Präposition","48":"Adverb","49":"Rektion","50":"Adverb","51":"Konnektor"},"why":{"46":"wie Sie ja sicherlich wissen — «как вы, наверное, знаете». keineswegs («ни в коем случае») противоречит смыслу.","47":"durch + Akk. … bedingt — «обусловленный чем-то»: durch meinen Umzug bedingt — из-за переезда.","48":"umgehend — «незамедлительно»: подтверждение нужно срочно — для договора аренды.","49":"jdn. um etw. bitten — просить о чём-то: Ich bitte Sie um ein Arbeitszeugnis.","50":"sich nochmals herzlich bedanken — «ещё раз сердечно поблагодарить». kaum («едва») по смыслу не подходит.","51":"nicht nur …, sondern (auch) — «не только…, но и»."},"extra":"Лишние: keineswegs, pro, kaum, das."},{"id":"s7t2","title":"Übung 7 · Teil 2","thema":"Anfrage","type":"abc","head":"Ihre Anfrage","paras":["Sehr geehrter Herr Kowalski,","vielen Dank für Ihr Interesse an {52}. Gerne erstellen wir Ihnen ein Angebot für 150 Paar Sicherheitsschuhe des Modells „Safe Step S3“. {53} brauchen wir noch einige Informationen von Ihnen.","Bitte teilen Sie uns mit, ob die Schuhe an Ihr Lager in Ulm oder an Ihre Zentrale in Augsburg geliefert werden sollen. Außerdem benötigen wir Angaben über den {54}.","Für die Größenauswahl sendet Ihnen unser Kundendienst gerne eine Tabelle zu.","Sollten in der Zwischenzeit {55}, wenden Sie sich bitte an Ihre Ansprechpartnerin, Frau Novak. Frau Novak kümmert sich um {56}, die bei der Bestellung auftreten können, und findet mit Ihnen eine Lösung.","Wir freuen uns auf {57}.","Mit freundlichen Grüßen<br>Sandra Weiß"],"items":[{"n":52,"o":["unserem Angebot","unseren Produkten","Ihren Bestellungen"],"a":1,"t":"Rektion","w":"Interesse an + Dat. — интерес к: an unseren Produkten. Предложения (Angebot) ещё нет — его только составят."},{"n":53,"o":["Trotzdem","Dagegen","Dafür"],"a":2,"t":"da-Wort","w":"dafür — «для этого»: чтобы составить предложение, нужна информация. trotzdem («тем не менее») и dagegen («напротив») — противопоставления здесь нет."},{"n":54,"o":["gewünschten Liefertermin","fröhlichen Feierabend","letzten Urlaub"],"a":0,"t":"Wortschatz","w":"Angaben über den gewünschten Liefertermin — сведения о желаемом сроке поставки."},{"n":55,"o":["alle Probleme gelöst sein","keine Wünsche bestehen","weitere Fragen auftauchen"],"a":2,"t":"Wortschatz","w":"Sollten weitere Fragen auftauchen, … — «если появятся вопросы». Остальные варианты противоречат смыслу."},{"n":56,"o":["alle Probleme","das Problem","jeden Fehler"],"a":0,"t":"Relativpronomen","w":"alle Probleme, die … auftreten können — относительное местоимение die (мн. ч.) подходит только к Probleme. Для das Problem было бы das, для jeden Fehler — den."},{"n":57,"o":["unseren kommenden Termin","Ihre baldige Rückmeldung","Ihre letzte Beschwerde"],"a":1,"t":"Wortschatz","w":"sich freuen auf Ihre baldige Rückmeldung — «будем рады вашему скорому ответу»."}]},{"id":"s8t1","title":"Übung 8 · Teil 1","thema":"Umschulung","type":"bank","head":"Umschulung","paras":["Sehr geehrte Damen und Herren,","da ich meinen Beruf als Elektriker aus gesundheitlichen Gründen nicht mehr ausüben kann, bewerbe ich mich {46} um einen Umschulungsplatz als Fachinformatiker für Systemintegration, den Sie auf Ihrer Website ausgeschrieben haben.","Schon seit Jahren helfe ich nicht nur meiner Familie, {47} auch Freunden und Nachbarn bei Problemen mit Computern und Netzwerken. Deshalb habe ich mich für diese Umschulung entschieden.","{48} meine Arbeit als Elektriker bin ich es gewohnt, sorgfältig und sicher zu arbeiten. Fehler können auf der Baustelle gefährlich sein, {49} ich immer sehr genau arbeite.","In Ihrer Anzeige steht, dass Sie Umschüler aus einem Umkreis von 30 km suchen. {50} ist für mich kein Problem, da ich bereit bin, nach Karlsruhe umzuziehen.","{51} wird meine Umschulung von der Agentur für Arbeit gefördert.","Ich würde mich sehr über eine Einladung zum Vorstellungsgespräch freuen.","Mit freundlichen Grüßen<br>Serhii Bondarenko"],"bank":[["a","dies"],["b","des Weiteren"],["c","obwohl"],["d","trotz"],["e","durch"],["f","sondern"],["g","weshalb"],["h","deren"],["i","hiermit"],["j","darüber"]],"key":{"46":"i","47":"f","48":"e","49":"g","50":"a","51":"b"},"cap":[48,50,51],"topic":{"46":"Adverb","47":"Konnektor","48":"Präposition","49":"Konnektor","50":"Pronomen","51":"Konnektor"},"why":{"46":"sich hiermit bewerben — «настоящим подаю заявку». Стандартная формула.","47":"nicht nur …, sondern auch — «не только…, но и».","48":"durch + Akk. — «благодаря»: durch meine Arbeit als Elektriker. trotz требовал бы Genitiv (meiner) и дал бы противоречие.","49":"weshalb — «поэтому, из-за чего»: союз с глаголом в конце (…, weshalb ich immer sehr genau arbeite). obwohl («хотя») даёт противоречие.","50":"dies — «это» в роли подлежащего: Dies ist für mich kein Problem.","51":"des Weiteren — «кроме того»: ещё один довод — переобучение оплачивает Agentur für Arbeit."},"extra":"Лишние: obwohl, trotz, deren, darüber."},{"id":"s8t2","title":"Übung 8 · Teil 2","thema":"Angebot","type":"abc","head":"Ihr Schreiben vom 08.09.20xx<br>Unser Angebot „Datenschutz im Büro“, Angebotsnr. 2025-117","paras":["Sehr geehrte Frau Hartmann,","zunächst möchten wir uns für {52} vom 08.09.20xx bedanken. Wie telefonisch besprochen, erhalten Sie mit diesem Schreiben {53} für eine Datenschutz-Schulung Ihrer Mitarbeiter. Die Schulung bietet Ihrem Unternehmen {54}.","Ihre Mitarbeiter lernen, personenbezogene Daten sicher zu verarbeiten, und Sie vermeiden hohe Bußgelder. Weitere Informationen finden Sie in dem {55}.","Die Preise haben wir, wie gewünscht, an die Größe Ihres Unternehmens angepasst. Bitte beachten Sie, dass wir die Schulung frühestens drei Wochen {56} können.","Bei Fragen stehe ich Ihnen jederzeit zur Verfügung. Wir freuen uns auf Ihren Auftrag und sichern Ihnen eine pünktliche und {57} der Schulung zu.","Mit freundlichen Grüßen<br>Florian Wolf"],"items":[{"n":52,"o":["Ihre Anfrage","Ihr Interesse","Ihren Auftrag"],"a":0,"t":"Wortschatz","w":"für Ihre Anfrage vom 08.09. — благодарим за запрос (в шапке: Ihr Schreiben vom 08.09.). Заказа ещё нет — его только ждут."},{"n":53,"o":["unsere Bestellung","unser Angebot","unsere Nachfrage"],"a":1,"t":"Wortschatz","w":"erhalten Sie unser Angebot — в ответ на запрос фирма присылает предложение."},{"n":54,"o":["viele Nachteile","hohe Bußgelder","zahlreiche Vorteile"],"a":2,"t":"Wortschatz","w":"zahlreiche Vorteile — дальше перечислены плюсы. Bußgelder (штрафы) как раз избегают."},{"n":55,"o":["beiliegenden Unterlagen","beigefügten Prospekt","versendeten Rechnung"],"a":1,"t":"Deklination","w":"in dem beigefügten Prospekt — dem требует мужского или среднего рода: der Prospekt. Unterlagen — мн. ч. (den), Rechnung — женский род (der)."},{"n":56,"o":["nach Auftragserteilung durchführen","mit Bekanntgabe erledigen","nach Zusage herstellen"],"a":0,"t":"Wortschatz","w":"nach Auftragserteilung durchführen — провести после получения заказа."},{"n":57,"o":["kundengerechte Bearbeitung","schnelle Kündigung","ordnungsgemäße Durchführung"],"a":2,"t":"Wortschatz","w":"eine ordnungsgemäße Durchführung zusichern — гарантировать надлежащее проведение."}],"extra":"Полезные слова: personenbezogene Daten — персональные данные; das Bußgeld — штраф."},{"id":"s9t1","title":"Übung 9 · Teil 1","thema":"Weiterbildung","type":"bank","head":"","paras":["Sehr geehrte Damen und Herren,","vielen Dank für die {46} Zusendung Ihres Kursprogramms. Unsere Mitarbeiter interessieren sich sowohl für die Excel-Grundlagen als {47} für den Aufbaukurs.","Wir haben dazu allerdings {48} einige Fragen. Können wir bis zu zwölf Personen für den Online-Kurs anmelden? Und haben Sie {49} Erfahrung mit Kursen für Mitarbeiter aus der Logistik? Wenn nicht, würden wir lieber einen Kurs vor Ort buchen.","Wegen der Schichtarbeit haben unsere Mitarbeiter erst ab 16:00 Uhr Zeit. Wäre es möglich, den Kurs {50} 16:30 Uhr zu beginnen?","{51} möchten wir wissen, ob wir die Kursgebühren per Rechnung mit einem Zahlungsziel von 14 Tagen bezahlen können.","Vielen Dank im Voraus.","Mit freundlichen Grüßen<br>Paul Hermann"],"bank":[["a","noch"],["b","gegen"],["c","ob"],["d","auch"],["e","jedoch"],["f","sondern"],["g","deshalb"],["h","schon"],["i","schnelle"],["j","des Weiteren"]],"key":{"46":"i","47":"d","48":"a","49":"h","50":"b","51":"j"},"cap":[51],"topic":{"46":"Deklination","47":"Konnektor","48":"Adverb","49":"Adverb","50":"Präposition","51":"Konnektor"},"why":{"46":"die schnelle Zusendung — «быстрая отправка». Нужно прилагательное: после die — окончание -e.","47":"sowohl … als auch — «как…, так и». Парная связка.","48":"noch einige Fragen — «ещё несколько вопросов».","49":"schon — «уже»: Haben Sie schon Erfahrung …? — есть ли у вас уже опыт.","50":"gegen + время — «около»: gegen 16:30 Uhr.","51":"des Weiteren — «кроме того»: следующий вопрос. deshalb («поэтому») не подходит — причины нет."},"extra":"Лишние: ob, jedoch, sondern, deshalb."},{"id":"s9t2","title":"Übung 9 · Teil 2","thema":"Angebot","type":"abc","head":"Angebot","paras":["Sehr geehrte Frau Brandt,","vielen Dank für Ihr {52} an unseren Produkten. Gerne unterbreiten wir Ihnen {53}:","<div class=\"shb-tw\"><table class=\"shb-t\"><tr><th>Pos.</th><th>Bezeichnung</th><th>Menge</th><th>Einzelpreis (EUR)</th><th>Gesamt (EUR)</th></tr><tr><td>1.</td><td>Beamer „Vision X5“</td><td>3</td><td>890,00</td><td>2.670,00</td></tr><tr><td>2.</td><td>Installation</td><td>pauschal</td><td>350,00</td><td>350,00</td></tr><tr><td></td><td></td><td></td><td>Summe netto</td><td>3.020,00</td></tr><tr><td></td><td></td><td></td><td>Umsatzsteuer 19 %</td><td>573,80</td></tr><tr><td></td><td></td><td></td><td>Rechnungsbetrag</td><td>3.593,80</td></tr></table></div>","Die Lieferzeit beträgt etwa zwei Wochen, nachdem {54} wurde. Der Rechnungsbetrag ist innerhalb von 30 Tagen {55}. Die Garantie beträgt zwei Jahre. Dieses Angebot ist vier Wochen gültig.","Wir hoffen, dass unser Angebot {56}. Bei Fragen stehen wir Ihnen gerne {57}.","Mit freundlichen Grüßen<br>Martin Schuster"],"items":[{"n":52,"o":["Anfrage","Bestellung","Interesse"],"a":2,"t":"Rektion","w":"Interesse an + Dat. — интерес к: Ihr Interesse an unseren Produkten. Anfrage и Bestellung — женского рода, было бы Ihre."},{"n":53,"o":["laufende Kosten","folgendes Angebot","weitere Zusagen"],"a":1,"t":"Wortschatz","w":"Gerne unterbreiten wir Ihnen folgendes Angebot — «представляем вам следующее предложение». Дальше таблица с ценами."},{"n":54,"o":["der Auftrag erteilt","die Anfrage beantwortet","die Lieferung bekannt"],"a":0,"t":"Nomen-Verb-Verbindung","w":"nachdem der Auftrag erteilt wurde — после того как будет выдан заказ. Поставка идёт после заказа, а не после ответа на запрос."},{"n":55,"o":["ohne Abzug zu zahlen","mit Umsatzsteuer zu verkaufen","als Rabatt zu verbuchen"],"a":0,"t":"Wortschatz","w":"ohne Abzug zu zahlen — «оплатить без вычетов (без скидки)»."},{"n":56,"o":["einen Abnehmer findet","keine Kunden hat","Ihre Zustimmung findet"],"a":2,"t":"Nomen-Verb-Verbindung","w":"Ihre Zustimmung finden — «встретить ваше одобрение», стандартная формула."},{"n":57,"o":["zur Beratung","zur Verfügung","zur Hilfe"],"a":1,"t":"Nomen-Verb-Verbindung","w":"jdm. zur Verfügung stehen — быть в распоряжении. zur Beratung стоит только в связке zur Beratung zur Verfügung stehen."}]},{"id":"s10t1","title":"Übung 10 · Teil 1","thema":"Kündigung","type":"bank","head":"Kündigung meines Arbeitsvertrags","paras":["Sehr geehrter Herr Krämer,","hiermit kündige ich meinen Arbeitsvertrag fristgerecht zum 31.08.20xx. {46} mein Mann eine Stelle in München angenommen hat, ziehen wir im Sommer um, und ich kann leider nicht in Ihrem Betrieb bleiben.","Gleichzeitig beantrage ich meinen restlichen Urlaub von fünf Tagen, {47} mein letzter Arbeitstag der 24.08.20xx ist.","Bitte bestätigen Sie mir den Eingang meiner Kündigung. Außerdem bitte ich Sie, mir ein qualifiziertes Arbeitszeugnis auszustellen und es mir {48} mit den übrigen Arbeitspapieren an meine neue Adresse in München zu senden.","Die Übergabe meiner Kunden an meine Kollegin bereite ich {49} vor. Die Einzelheiten können wir gerne in einem Gespräch klären.","Ich habe in Ihrem Team immer {50} gern gearbeitet und viel gelernt. {51} danke ich Ihnen herzlich und wünsche Ihnen und dem ganzen Team alles Gute.","Freundliche Grüße<br>Olena Kravets"],"bank":[["a","als"],["b","da"],["c","dafür"],["d","dagegen"],["e","sehr"],["f","selbstverständlich"],["g","sodass"],["h","sowohl"],["i","zu"],["j","zusammen"]],"key":{"46":"b","47":"g","48":"j","49":"f","50":"e","51":"c"},"cap":[46,51],"topic":{"46":"Konnektor","47":"Konnektor","48":"Adverb","49":"Adverb","50":"Adverb","51":"da-Wort"},"why":{"46":"da — «так как»: причина в начале предложения (Da mein Mann … angenommen hat, …).","47":"sodass — «так что»: следствие — с пятью днями отпуска последним рабочим днём будет 24.08.","48":"zusammen mit — «вместе с»: прислать справку вместе с документами.","49":"selbstverständlich — «само собой разумеется»: передачу клиентов я, конечно, подготовлю.","50":"sehr gern — «очень охотно»: мне всегда очень нравилось работать в команде.","51":"dafür danke ich Ihnen — «за это благодарю»: danken für → dafür."},"extra":"Лишние: als, dagegen, sowohl, zu."},{"id":"s10t2","title":"Übung 10 · Teil 2","thema":"Beschwerde","type":"abc","head":"Weitere Zusammenarbeit","paras":["Sehr geehrter Herr Lindner,","am 3. März 20XX hatte ich Ihrer Agentur {52}, eine neue Website für unser Restaurant zu erstellen. Ihr Mitarbeiter, Herr Berger, hat sich danach mit mir {53} und einen ersten Termin für den 10. März vereinbart. Leider ist Herr Berger zu diesem Termin nicht gekommen.","Am nächsten Tag hat er sich telefonisch entschuldigt und {54}, am 14. März vorbeizukommen. Doch auch diesmal hat er {55}.","Da ich Herrn Berger nicht mehr erreiche, wende ich mich direkt an Sie. Bitte melden Sie sich {56} dieser Woche bei mir, damit wir besprechen können, wie es weitergeht. Ich bin sicher, dass wir gemeinsam {57}.","Mit freundlichen Grüßen<br>Elena Marino"],"items":[{"n":52,"o":["die Kündigung geschickt","den Auftrag erteilt","die Rechnung bezahlt"],"a":1,"t":"Nomen-Verb-Verbindung","w":"jdm. den Auftrag erteilen, etw. zu tun — поручить кому-то работу (выдать заказ)."},{"n":53,"o":["in Verbindung gesetzt","zur Sprache gebracht","zur Verfügung gestellt"],"a":0,"t":"Nomen-Verb-Verbindung","w":"sich mit jdm. in Verbindung setzen — связаться с кем-то. zur Sprache bringen — поднять тему; zur Verfügung stellen — предоставить."},{"n":54,"o":["mir sofort geholfen","mich kurz beantwortet","mir fest zugesagt"],"a":2,"t":"Wortschatz","w":"jdm. fest zusagen, etw. zu tun — твёрдо пообещать. Дальше: sein Versprechen — его обещание."},{"n":55,"o":["den Zweck nicht erfüllt","keine Verabredung getroffen","sein Versprechen nicht gehalten"],"a":2,"t":"Nomen-Verb-Verbindung","w":"ein Versprechen halten / nicht halten — сдержать / не сдержать обещание. Встречу они как раз назначили."},{"n":56,"o":["in Gang","im Laufe","im Grunde"],"a":1,"t":"Präposition","w":"im Laufe + Gen. — «в течение»: im Laufe dieser Woche. in Gang — «в ходу», im Grunde — «по сути»."},{"n":57,"o":["eine Lösung finden","am Ende sind","in Ordnung gehen"],"a":0,"t":"Nomen-Verb-Verbindung","w":"eine Lösung finden — найти решение. am Ende sein — выдохнуться; in Ordnung gehen — «быть в порядке»."}]},{"id":"s11t1","title":"Übung 11 · Teil 1","thema":"Bewerbung / Termin","type":"bank","head":"Betreff: Ihre Einladung zum Vorstellungsgespräch – Kennziffer KD-2047","paras":["Sehr geehrte Frau Albrecht,","Ende April habe ich mich bei Ihnen um die Stelle als Mechatroniker im Kundendienst beworben. Gestern habe ich Ihre Einladung zu einem Vorstellungsgespräch am 10. Juni erhalten, {46} ich mich sehr gefreut habe.","Leider muss ich Sie {47} bitten, das Gespräch zu verschieben, {48} genau an diesem Tag meine schriftliche Abschlussprüfung im Umschulungskurs stattfindet. Es wäre schön, wenn das Gespräch nicht {49} meiner Prüfungswoche vom 8. bis 12. Juni, sondern in der Woche danach stattfinden könnte. {50} dem 15. Juni bin ich zeitlich völlig flexibel.","Wie telefonisch besprochen, sende ich Ihnen anbei die Beurteilung aus meinem Praktikumsbetrieb. Das Abschlusszeugnis bekomme ich leider {51} Ende Juli; ich reiche es Ihnen dann sofort nach.","Vielen Dank für Ihr Verständnis.","Mit freundlichen Grüßen<br>Andrij Melnyk"],"bank":[["a","ab"],["b","demnächst"],["c","denn"],["d","erst"],["e","nun"],["f","seit"],["g","trotz"],["h","während"],["i","weil"],["j","worüber"]],"key":{"46":"j","47":"e","48":"i","49":"h","50":"a","51":"d"},"cap":[50],"topic":{"46":"Relativpronomen","47":"Adverb","48":"Konnektor","49":"Präposition","50":"Präposition","51":"Adverb"},"why":{"46":"worüber — sich freuen über + Akk.: радоваться тому, что уже получил (приглашению). Слово на wo- заменяет «über die Einladung» и открывает придаточное — глагол habe в конце.","47":"nun — «теперь, однако»: вежливая вставка в просьбу. demnächst («в ближайшее время») с просьбой не сочетается.","48":"weil — причина, глагол stattfindet стоит в конце. denn тоже значит «потому что», но после него прямой порядок слов: denn genau an diesem Tag findet … statt.","49":"während + Gen. — «во время»: während meiner Prüfungswoche. trotz тоже требует Genitiv, но значит «несмотря на» — по смыслу не подходит.","50":"ab + Dat. — «начиная с» (о будущем): Ab dem 15. Juni. seit — «с … и до сих пор», только о том, что уже началось.","51":"erst — «только, не раньше»: leider erst Ende Juli — справка придёт поздно, поэтому её дошлют."},"extra":"Лишние: demnächst, denn, seit, trotz."},{"id":"s11t2","title":"Übung 11 · Teil 2","thema":"Angebot","type":"abc","head":"Angebot Kassensystem „KS 200“","paras":["Sehr geehrte Frau Weidner,","vielen Dank für {52} vom 3. März zu unserem Kassensystem KS 200.","Mit dem KS 200 bieten wir Ihnen ein zu {53} passendes System, das Sie schnell in allen drei Filialen Ihrer Bäckerei einsetzen können.","In der Anlage finden Sie unsere {54} mit allen Liefer- und Zahlungsbedingungen. Bei unserer Kalkulation konnten wir innerhalb des von Ihnen {55} bleiben. Ein Exemplar unseres neuen Katalogs schicken wir Ihnen zusätzlich per Post.","Das System können wir spätestens zwei Wochen nach {56} installieren.","Über Ihren Auftrag würden wir uns sehr freuen und garantieren Ihnen {57} nach Ihren Wünschen.","Mit freundlichen Grüßen<br>Tobias Wendt<br>Vertrieb"],"items":[{"n":52,"o":["Ihre Bestellung","Ihre Reklamation","Ihre Anfrage"],"a":2,"t":"Wortschatz","w":"Ihre Anfrage — это Angebot: клиентка пока только спросила о кассе. Bestellung — уже заказ, а в конце фирма ещё только надеется на Auftrag; Reklamation — жалоба на купленный товар."},{"n":53,"o":["Ihren betrieblichen Anforderungen","Ihrer offenen Rechnung","Ihren hohen Ausgaben"],"a":0,"t":"Wortschatz","w":"zu Ihren betrieblichen Anforderungen passend — «подходящий под требования вашего предприятия». Все три варианта стоят в Dativ после zu — решает смысл."},{"n":54,"o":["neue Mahnung","aktuelle Preisliste","letzte Gutschrift"],"a":1,"t":"Wortschatz","w":"aktuelle Preisliste — к Angebot прикладывают прайс-лист с условиями поставки и оплаты. Mahnung — напоминание о долге, Gutschrift — кредит-нота (возврат денег)."},{"n":55,"o":["bezahlten Rechnungsbetrags","genannten Budgetrahmens","erhaltenen Rabatts"],"a":1,"t":"Wortschatz","w":"innerhalb des genannten Budgetrahmens — «в рамках названного вами бюджета» (innerhalb + Gen.). Ничего ещё не оплачено, и скидки не было."},{"n":56,"o":["eingereichter Kündigung","geäußerter Beschwerde","erfolgter Auftragserteilung"],"a":2,"t":"Nomen-Verb-Verbindung","w":"nach erfolgter Auftragserteilung — «после выдачи заказа» (einen Auftrag erteilen), устойчивая формула. Kündigung и Beschwerde к установке кассы не относятся."},{"n":57,"o":["eine termingerechte Installation","eine sofortige Stornierung","eine spätere Mahnung"],"a":0,"t":"Wortschatz","w":"eine termingerechte Installation — «установка точно в срок»: стандартное обещание в Angebot. Stornierung — отмена заказа."}]},{"id":"s12t1","title":"Übung 12 · Teil 1","thema":"Bewerbung / Nachfrage","type":"bank","head":"Betreff: Unser Gespräch am 14. Mai auf dem Karrieretag Stuttgart","paras":["Sehr geehrter Herr Kessler,","am 14. Mai habe ich mich Ihnen auf dem Karrieretag in Stuttgart am Stand Ihres Unternehmens persönlich vorgestellt und Ihnen {46} auch gleich meine Bewerbungsmappe überreicht. Nach einem ausführlichen Gespräch über die Aufgaben in der Disposition haben Sie mir angeboten, meine Unterlagen an Ihren Logistikleiter weiterzugeben, {47} ich mich sehr gefreut habe.","Leider habe ich {48} nichts mehr von Ihrem Unternehmen gehört und bin nun unsicher, ob meine Unterlagen vielleicht verloren gegangen sind. {49} wende ich mich heute schriftlich an Sie und füge meine Bewerbung zur Sicherheit noch einmal bei.","Für Ihre Disposition habe ich bereits einige Ideen, {50} Sie Leerfahrten vermeiden und Ihre Touren noch effizienter planen können. Gerne stelle ich Ihnen diese in einem persönlichen Gespräch vor.","{51} ich zurzeit nicht berufstätig bin, könnte ich die Stelle kurzfristig antreten.","Vielen Dank im Voraus und mit freundlichen Grüßen<br>Oleksandr Tkachenko"],"bank":[["a","da"],["b","dabei"],["c","deshalb"],["d","mittlerweile"],["e","ob"],["f","seitdem"],["g","wann"],["h","wie"],["i","worauf"],["j","worüber"]],"key":{"46":"b","47":"j","48":"f","49":"c","50":"h","51":"a"},"cap":[49,51],"topic":{"46":"da-Wort","47":"Relativpronomen","48":"Adverb","49":"Konnektor","50":"Konnektor","51":"Konnektor"},"why":{"46":"dabei — «при этом, заодно»: на той же встрече сразу отдал документы. da здесь звучало бы разговорно, и оно нужно в №51.","47":"worüber — sich freuen über: радоваться тому, что уже произошло (предложению передать документы). worauf — sich freuen auf: радоваться будущему.","48":"seitdem — «с тех пор»: после ярмарки ничего не слышал. mittlerweile — «тем временем, уже» — говорит о переменах, а их как раз нет.","49":"Deshalb — «поэтому» + инверсия (wende ich): ответа нет → пишу сам. Da открыло бы придаточное — глагол ушёл бы в конец.","50":"wie — «как»: идеи, как избежать порожних рейсов (Leerfahrten). ob — «ли», wann — «когда».","51":"Da — «так как»: причина в начале, глагол bin в конце, потом инверсия könnte ich. После deshalb сразу шёл бы глагол."},"extra":"Лишние: mittlerweile, ob, wann, worauf."},{"id":"s12t2","title":"Übung 12 · Teil 2","thema":"Angebot","type":"abc","head":"Angebot Headsets","paras":["Sehr geehrte Frau Becker,","vielen Dank für Ihr Interesse an unseren Produkten. Bezug nehmend auf {52} vom 8. Oktober empfehlen wir Ihnen für Ihr Kundenservice-Team die folgenden Headsets:","<div class=\"shb-tw\"><table class=\"shb-t\"><tr><th>Modell</th><th>Preis</th></tr><tr><td><b>ClearTalk Duo</b><br>kabellos, Akku 20 Std.,<br>Geräuschunterdrückung</td><td>89,00 €</td></tr><tr><td><b>ClearTalk Mono</b><br>USB-Anschluss,<br>flexibler Mikrofonarm</td><td>49,00 €</td></tr></table></div>","Weitere technische Einzelheiten finden Sie {53}. Die {54} inklusive der gesetzlichen Mehrwertsteuer von 19 %.","Zahlungsbedingungen: innerhalb von 14 Tagen nach Rechnungsdatum abzüglich 2 % Skonto oder innerhalb von 30 Tagen netto. {55} innerhalb von drei Werktagen nach Eingang Ihrer Bestellung.","Wir würden uns freuen, Sie als neue Kundin zu gewinnen. Da es sich bei Ihrer Bestellung um {56} handeln würde, gewähren wir Ihnen gern einen Neukundenrabatt von 10 %.","Für Rückfragen stehen wir Ihnen jederzeit gern {57}.","Mit freundlichen Grüßen<br>Kathrin Vogel<br>Vertrieb"],"items":[{"n":52,"o":["Ihren Auftrag","Ihre Anfrage","Ihre Rechnung"],"a":1,"t":"Wortschatz","w":"Bezug nehmend auf Ihre Anfrage — «ссылаясь на ваш запрос»: клиентка спросила, фирма рекомендует модели. Auftrag — уже заказ; Rechnung выставляет продавец, а не клиент."},{"n":53,"o":["in unseren Zahlungsbedingungen","auf Ihrer Rechnung","im beigefügten Datenblatt"],"a":2,"t":"Wortschatz","w":"im beigefügten Datenblatt — технические данные ищут в приложенном описании товара. В условиях оплаты их нет, а счёта ещё нет."},{"n":54,"o":["Preise verstehen sich","Preise beziehen sich","Preise ergeben sich"],"a":0,"t":"Wortschatz","w":"Die Preise verstehen sich inklusive/zuzüglich MwSt. — устойчивая формула: «цены указаны с НДС / без НДС». sich beziehen требует auf, sich ergeben — aus."},{"n":55,"o":["Die Zahlung erfolgt","Die Reklamation erfolgt","Die Lieferung erfolgt"],"a":2,"t":"Wortschatz","w":"Die Lieferung erfolgt — «поставка производится»: 3 рабочих дня после заказа — это срок поставки. Об оплате уже сказано выше (14 или 30 дней после счёта)."},{"n":56,"o":["einen Erstauftrag","einen Folgeauftrag","eine Stornierung"],"a":0,"t":"Wortschatz","w":"einen Erstauftrag — первый заказ новой клиентки, отсюда скидка для новых клиентов (Neukundenrabatt). Folgeauftrag — повторный заказ, Stornierung — отмена."},{"n":57,"o":["zur Auswahl","zur Verfügung","zur Last"],"a":1,"t":"Nomen-Verb-Verbindung","w":"jdm. zur Verfügung stehen — «быть в распоряжении». zur Auswahl stehen говорят о товарах («на выбор»), а «быть в тягость» — zur Last fallen."}]},{"id":"s13t1","title":"Übung 13 · Teil 1","thema":"Nach dem Vorstellungsgespräch","type":"bank","head":"Betreff: Mein Vorstellungsgespräch am 22. Oktober","paras":["Sehr geehrte Frau Brandner,","{46} vielen Dank für das angenehme und offene Gespräch am 22. Oktober. Ich habe mich bei Ihnen sofort wohlgefühlt. Besonders beeindruckt hat mich, {47} Sie sich so viel Zeit für meine Fragen genommen haben.","Ihre Erläuterungen zu den Abläufen im Einkauf, {48} zur Zusammenarbeit mit den Lieferanten in Osteuropa, waren für mich sehr aufschlussreich. Das Gespräch hat meinen Wunsch bestärkt, in Ihrem Unternehmen zu arbeiten, und ich bin überzeugt, dass ich mit meiner Erfahrung gut in Ihr Team passen würde.","{49} möchte ich mich heute nach dem aktuellen Stand des Auswahlverfahrens erkundigen. Ich würde gern erfahren, ob Sie schon abschätzen können, {50} eine Entscheidung fallen wird.","{51} Sie noch weitere Unterlagen von mir benötigen, können Sie sich jederzeit telefonisch oder per E-Mail an mich wenden.","Ich freue mich darauf, bald von Ihnen zu hören.","Mit freundlichen Grüßen<br>Iryna Savchenko"],"bank":[["a","darüber"],["b","dass"],["c","denn"],["d","deshalb"],["e","jedoch"],["f","nochmals"],["g","vor allem"],["h","wann"],["i","weil"],["j","wenn"]],"key":{"46":"f","47":"b","48":"g","49":"d","50":"h","51":"j"},"cap":[46,49,51],"topic":{"46":"Adverb","47":"Konnektor","48":"Adverb","49":"Konnektor","50":"Konnektor","51":"Konnektor"},"why":{"46":"Nochmals vielen Dank — «ещё раз большое спасибо»: лично спасибо уже сказали на собеседовании. vor allem нужно в №48.","47":"dass — «то, что»: придаточное заменяет подлежащее (Besonders beeindruckt hat mich, dass …). С weil или wenn у глагола hat beeindruckt не было бы подлежащего.","48":"vor allem — «прежде всего, особенно»: уточняет, что именно было интересно.","49":"Deshalb — «поэтому» + инверсия (möchte ich): хочу у вас работать → спрашиваю о статусе. После denn был бы прямой порядок: denn ich möchte …","50":"wann — косвенный вопрос «когда»: abschätzen, wann … wenn — «если» или «когда (каждый раз)», косвенный вопрос не вводит.","51":"Wenn — условие «если понадобятся документы», дальше инверсия können Sie. С weil вышло бы, что документы точно нужны."},"extra":"Лишние: darüber, denn, jedoch, weil."},{"id":"s13t2","title":"Übung 13 · Teil 2","thema":"Angebot","type":"abc","head":"Angebot Büroumzug","paras":["Sehr geehrter Herr Novak,","vielen Dank für {52} an unserem Umzugsservice.","Nach der Besichtigung Ihrer Büroräume am 3. Mai schicke ich Ihnen heute mein Angebot für {53}:","<div class=\"shb-tw\"><table class=\"shb-t\"><tr><th>Leistung</th><th>Preis</th></tr><tr><td>Möbel abbauen und<br>verpacken (12 Plätze)</td><td>960,00 €</td></tr><tr><td>Transport pauschal<br>(Lkw, 3 Mitarbeiter)</td><td>1.150,00 €</td></tr><tr><td>Aufbau am neuen<br>Standort (12 Plätze)</td><td>840,00 €</td></tr><tr><th>Summe netto</th><th>2.950,00 €</th></tr></table></div>","Termin: 26. und 27. Juni","Die Preise verstehen sich {54} der gesetzlichen Mehrwertsteuer. In allen Positionen sind die Kosten für Kartons und Verpackungsmaterial bereits enthalten. {55} gehen wir davon aus, dass Ihre Mitarbeiterinnen und Mitarbeiter ihre Schränke und Schreibtische vor dem Umzug selbst ausräumen.","Es gelten folgende Zahlungsbedingungen: Bei Auftragserteilung bitten wir um eine Anzahlung von 30 %. Der Restbetrag ist 14 Tage nach Rechnungsdatum fällig. Bei Zahlung innerhalb von sieben Tagen {56} von 2 %.","Wir hoffen, dass unser Angebot Ihren Vorstellungen entspricht, und freuen uns auf Ihren Auftrag. Selbstverständlich {57} jederzeit zur Verfügung.","Mit freundlichen Grüßen<br>Markus Feldmann<br>Feldmann Umzüge GmbH"],"items":[{"n":52,"o":["Ihr Interesse","Ihre Frage","Ihren Auftrag"],"a":0,"t":"Rektion","w":"Interesse an + Dat. — интерес к чему-то: Ihr Interesse an unserem Umzugsservice. Frage an требует Akkusativ (an unseren …), а заказа ещё нет — это Angebot."},{"n":53,"o":["die erledigten Arbeiten","die durchzuführenden Arbeiten","die bezahlten Leistungen"],"a":1,"t":"Verbform","w":"die durchzuführenden Arbeiten — «работы, которые предстоит выполнить» (zu + Partizip I). Angebot всегда о будущих работах, а erledigt и bezahlt — о прошлом."},{"n":54,"o":["abzüglich","anstelle","zuzüglich"],"a":2,"t":"Präposition","w":"zuzüglich + Gen. — «плюс»: в таблице цены без налога (Summe netto), НДС прибавляется. abzüglich — «минус», так говорят о скидке: abzüglich 2 % Skonto."},{"n":55,"o":["Nach Ihrer Reklamation","Bei unserem Kostenvoranschlag","Trotz unserer Besichtigung"],"a":1,"t":"Wortschatz","w":"Bei unserem Kostenvoranschlag — «при составлении сметы» фирма исходит из того, что шкафы освободят сами сотрудники. Reklamation ещё быть не может, trotz — нелогично."},{"n":56,"o":["gewähren wir Ihnen einen Skonto","berechnen wir Ihnen einen Zuschlag","verlangen wir eine Mahngebühr"],"a":0,"t":"Nomen-Verb-Verbindung","w":"einen Skonto gewähren — предоставить скидку за быструю оплату. За раннюю оплату не берут ни надбавку (Zuschlag), ни плату за напоминание (Mahngebühr)."},{"n":57,"o":["stellen wir Ihnen für Rückfragen","sind wir Ihnen für Rückfragen","stehen wir Ihnen für Rückfragen"],"a":2,"t":"Nomen-Verb-Verbindung","w":"jdm. zur Verfügung stehen — «быть в распоряжении». zur Verfügung stellen требует объекта (что предоставляем), а «sind … zur Verfügung» так не говорят."}]},{"id":"s14t1","title":"Übung 14 · Teil 1","thema":"Nach dem Vorstellungsgespräch","type":"bank","head":"Betreff: Unser Gespräch am 5. März","paras":["Sehr geehrte Frau Lindemann,","vielen Dank, dass Sie mir am 5. März die Gelegenheit gegeben haben, mich nach meiner schriftlichen Bewerbung {46} persönlich bei Ihnen vorzustellen. Dass Sie mir nach dem Gespräch sogar die Rezeption und einige Gästezimmer gezeigt haben, hat mich sehr gefreut – {47} hatte ich gar nicht gerechnet.","{48} gut hat mir gefallen, dass neue Mitarbeiterinnen und Mitarbeiter in den ersten Wochen von einer erfahrenen Kollegin begleitet werden.","Ein wenig verunsichert hat mich Ihre Frage {49}, wie ich mit einer schwierigen Beschwerde umgehen würde. {50} bin ich mir aber sicher, dass ich mit meiner Erfahrung aus zwei Stadthotels gut in Ihr Team passen würde.","Wie besprochen gebe ich Ihnen heute Rückmeldung: Ich bin {51} – wie schon vor unserem Gespräch – sehr an der Stelle interessiert und würde mich über eine Zusage freuen.","Mit freundlichen Grüßen<br>Natalia Horbenko"],"bank":[["a","auch"],["b","besonders"],["c","danach"],["d","damit"],["e","daran"],["f","davon"],["g","jetzt"],["h","kaum"],["i","nicht"],["j","weiterhin"]],"key":{"46":"a","47":"d","48":"b","49":"c","50":"g","51":"j"},"cap":[48,50],"topic":{"46":"Adverb","47":"da-Wort","48":"Adverb","49":"da-Wort","50":"Adverb","51":"Adverb"},"why":{"46":"auch — «также, ещё и»: после письменной заявки — ещё и лично.","47":"damit — rechnen mit → damit hatte ich nicht gerechnet: «на это я не рассчитывала». daran — от denken an («об этом не подумала»), с rechnen не сочетается.","48":"Besonders — «особенно»: Besonders gut hat mir gefallen … nicht противоречит смыслу: дальше идёт похвала.","49":"danach — die Frage nach etw. → Ihre Frage danach, wie … («ваш вопрос о том, как…»). davon и daran к слову Frage не подходят.","50":"Jetzt — «теперь»: тогда была неуверенность, а теперь уверенность (Jetzt bin ich mir aber sicher). Инверсия — глагол bin сразу после наречия.","51":"weiterhin — «по-прежнему, и дальше»: интерес сохраняется (wie schon vor unserem Gespräch). kaum и nicht противоречат желанию получить Zusage."},"extra":"Лишние: daran, davon, kaum, nicht."},{"id":"s14t2","title":"Übung 14 · Teil 2","thema":"Beanstandung","type":"abc","head":"Ihre Beanstandung unserer Zahlungserinnerung","paras":["Sehr geehrter Herr Schäfer,","Ihr Schreiben vom 15. September ist heute bei uns eingegangen. Sie weisen uns darauf hin, dass der Rechnungsbetrag von 1.240 Euro für die am 28. August gelieferten Bürostühle bereits am 2. September {52}.","Bitte entschuldigen Sie unser Versehen. Wir haben die Angelegenheit sofort geprüft und konnten {53}: Wegen einer falschen Kundennummer im Verwendungszweck war Ihre Überweisung einem anderen Kundenkonto zugeordnet worden. Inzwischen haben wir die Zahlung richtig gebucht. Ihr Kundenkonto ist {54}, und unsere Zahlungserinnerung vom 12. September ist gegenstandslos.","{55} für die entstandenen Unannehmlichkeiten erhalten Sie bei Ihrer nächsten Bestellung einen Preisnachlass von 5 %. Wir entschuldigen uns noch einmal und versichern Ihnen, dass wir unsere Abläufe verbessern werden, damit solche {56} künftig nicht mehr vorkommen.","Wir freuen uns auf {57} und verbleiben","mit freundlichen Grüßen<br>Petra Kühn<br>Buchhaltung"],"items":[{"n":52,"o":["angemahnt wurde","storniert wurde","überwiesen wurde"],"a":2,"t":"Verbform","w":"überwiesen wurde — пассив: сумма «была переведена» клиентом (Überweisung). angemahnt — это сделала сама фирма (напоминание от 12.09.), storniert — «отменено»."},{"n":53,"o":["die Lieferung stornieren","den Fehler aufklären","die Mahnung zustellen"],"a":1,"t":"Wortschatz","w":"den Fehler aufklären — «выяснить, в чём ошибка»: после двоеточия как раз объяснение. Отменять поставку или отправлять напоминание нелогично."},{"n":54,"o":["somit ausgeglichen","somit überzogen","somit gesperrt"],"a":0,"t":"Wortschatz","w":"ausgeglichen — «без задолженности»: платёж учтён, долга нет. überzogen — о банковском счёте в минусе, gesperrt — «заблокирован»."},{"n":55,"o":["Als Entgegenkommen","Zur Erinnerung","Im Auftrag"],"a":0,"t":"Wortschatz","w":"Als Entgegenkommen — «в знак доброй воли»: скидка как компенсация за неудобства. Zur Erinnerung — «на память / для напоминания», Im Auftrag — «по поручению» (i. A. в подписи)."},{"n":56,"o":["Überweisungen","Preisnachlässe","Fehlbuchungen"],"a":2,"t":"Wortschatz","w":"Fehlbuchungen — «ошибочные проводки»: обещают, что такое не повторится. Überweisungen фирма как раз хочет получать."},{"n":57,"o":["eine rasche Zahlung","die weitere Zusammenarbeit","Ihre nächste Beanstandung"],"a":1,"t":"Wortschatz","w":"die weitere Zusammenarbeit — стандартная концовка. Клиент уже заплатил, поэтому eine rasche Zahlung нелогично."}]},{"id":"s15t1","title":"Übung 15 · Teil 1","thema":"Bewerbung / Nachfrage","type":"bank","head":"Betreff: Meine Bewerbung vom 2. März","paras":["Sehr geehrte Damen und Herren,","am 2. März habe ich mich bei Ihnen um die Stelle als Fachkraft für Lagerlogistik beworben. Am 10. März haben Sie mir den Eingang meiner Unterlagen bestätigt, {46} vielen Dank. Inzwischen sind sieben Wochen vergangen, und ich warte {47} noch auf eine Antwort.","Ich möchte noch einmal betonen, dass ich sehr gern in Ihrem Logistikzentrum arbeiten würde. Eine baldige Antwort wäre für mich auch deshalb wichtig, {48} mein jetziger Arbeitgeber sein Lager in Ludwigsburg zum Ende des Quartals schließt. {49} muss ich mich so schnell wie möglich nach einer neuen Stelle umsehen.","Ich bin überzeugt, dass ich {50} meiner Kenntnisse in modernen Lagerverwaltungssystemen gut in Ihr Team passen würde.","Sollten {51} Unterlagen fehlen, geben Sie mir bitte kurz Bescheid. Für eine schnelle Rückmeldung wäre ich Ihnen sehr dankbar.","Mit freundlichen Grüßen<br>Serhii Bondarenko"],"bank":[["a","aufgrund"],["b","da"],["c","daher"],["d","dafür"],["e","denn"],["f","immer"],["g","mit"],["h","noch"],["i","sobald"],["j","trotz"]],"key":{"46":"d","47":"f","48":"b","49":"c","50":"a","51":"h"},"cap":[49],"topic":{"46":"da-Wort","47":"Adverb","48":"Konnektor","49":"Konnektor","50":"Präposition","51":"Adverb"},"why":{"46":"dafür — danken für → dafür vielen Dank: «за это большое спасибо».","47":"immer noch — «всё ещё»: ответа до сих пор нет.","48":"da — «так как»: причина, глагол schließt в конце. deshalb …, da — типичная пара. После denn был бы прямой порядок: denn mein Arbeitgeber schließt …","49":"Daher — «поэтому» + инверсия (muss ich): склад закрывается → нужно искать работу.","50":"aufgrund + Gen. — «благодаря, на основании»: aufgrund meiner Kenntnisse (Gen. Pl.). mit требует Dativ: mit meinen Kenntnissen; trotz — «несмотря на» — нелогично.","51":"noch — «ещё»: если ещё каких-то документов не хватает. Sollten … fehlen = Falls … fehlen — условие без союза."},"extra":"Лишние: denn, mit, sobald, trotz."},{"id":"s15t2","title":"Übung 15 · Teil 2","thema":"Anfrage","type":"abc","head":"Anfrage Kantinenverpflegung","paras":["Sehr geehrte Damen und Herren,","wir sind ein Maschinenbaubetrieb in Rottweil mit rund 120 Beschäftigten. Da unser bisheriger Caterer zum 30. Juni {52}, suchen wir einen neuen Partner für die Verpflegung unserer Belegschaft. {53} unseres Geschäftspartners, der Firma Hellwig Metallbau, wenden wir uns heute an Sie.","Der Auftrag umfasst {54}:","– Mittagessen montags bis freitags, täglich mindestens ein vegetarisches Gericht<br>– belegte Brötchen und Kaffee für die Frühschicht ab 6.00 Uhr<br>– zweimal im Jahr ein Buffet für unsere Betriebsfeiern","Wir bitten Sie, bei Ihrer Planung unsere von 6.00 bis 22.00 Uhr {55} zu berücksichtigen.","Sollten Sie freie Kapazitäten haben, senden Sie uns bitte bis zum 15. Mai {56} zu. Für eine Besichtigung unserer Küche können Sie mit unserem Betriebsleiter, Herrn Kolb, gern {57}.","Mit freundlichen Grüßen<br>Daniela Roth<br>Personalabteilung"],"items":[{"n":52,"o":["seinen Betrieb erweitert","seinen Betrieb einstellt","seine Preise senkt"],"a":1,"t":"Nomen-Verb-Verbindung","w":"den Betrieb einstellen — «прекращать работу»: поэтому и ищут нового партнёра. Расширение или снижение цен поиск не объясняет."},{"n":53,"o":["Auf Empfehlung","Im Laufe","Zwecks Prüfung"],"a":0,"t":"Präposition","w":"auf Empfehlung + Gen. — «по рекомендации»: Auf Empfehlung unseres Geschäftspartners. im Laufe — «в течение» (о времени), zwecks — «с целью»."},{"n":54,"o":["folgende Gebäude","folgende Mitarbeiter","folgende Leistungen"],"a":2,"t":"Wortschatz","w":"folgende Leistungen — дальше перечислены услуги (обеды, завтраки, буфет), а не здания и не сотрудники."},{"n":55,"o":["geschlossenen Abteilungen","gekündigten Verträge","laufenden Schichten"],"a":2,"t":"Verbform","w":"die von 6 bis 22 Uhr laufenden Schichten — причастие I как определение: «смены, которые идут с 6 до 22». Остальное по смыслу не подходит."},{"n":56,"o":["eine verbindliche Bestellung","ein unverbindliches Angebot","eine Auftragsbestätigung"],"a":1,"t":"Wortschatz","w":"ein unverbindliches Angebot — поставщик присылает предложение без обязательств. Bestellung отправляет заказчик, Auftragsbestätigung — подтверждение уже выданного заказа."},{"n":57,"o":["einen Termin vereinbaren","eine Frist setzen","einen Antrag stellen"],"a":0,"t":"Nomen-Verb-Verbindung","w":"einen Termin vereinbaren — договориться о встрече (осмотр кухни). eine Frist setzen — установить срок, einen Antrag stellen — подать заявление."}]},{"id":"s16t1","title":"Übung 16 · Teil 1","thema":"Kündigung / Frage","type":"bank","head":"Betreff: Frage zum Ende meines Arbeitsverhältnisses","paras":["Sehr geehrte Frau Baumann,","wie ich Ihnen gestern in einem kurzen Gespräch {46} angedeutet habe, werde ich das Unternehmen leider verlassen. {47} ich meine Kündigung offiziell einreiche, möchte ich jedoch noch eine Frage mit Ihnen klären.","Ich habe einen Platz in einer Vollzeit-Weiterbildung zum staatlich geprüften Techniker bekommen und mich nach langem Überlegen {48} entschlossen, diese Chance zu nutzen. Der Lehrgang beginnt schon am 1. Juli.","Natürlich weiß ich, dass meine Kündigungsfrist drei Monate beträgt. {49} habe ich noch 15 Tage Resturlaub. Ich würde daher gern wissen, {50} Sie damit einverstanden wären, dass ich diesen Urlaub ab dem 8. Juni nehme und Sie mich danach bis zum Ende der Kündigungsfrist freistellen.","Für eine kurze Rückmeldung bis Ende der Woche wäre ich Ihnen sehr dankbar. {51} ich Ihre Antwort habe, reiche ich meine Kündigung schriftlich ein.","Mit freundlichen Grüßen<br>Viktoria Lysenko"],"bank":[["a","allerdings"],["b","bereits"],["c","bevor"],["d","damit"],["e","dass"],["f","dazu"],["g","mehrfach"],["h","ob"],["i","sobald"],["j","vor"]],"key":{"46":"b","47":"c","48":"f","49":"a","50":"h","51":"i"},"cap":[47,49,51],"topic":{"46":"Adverb","47":"Konnektor","48":"da-Wort","49":"Konnektor","50":"Konnektor","51":"Konnektor"},"why":{"46":"bereits — «уже»: как я уже намекала. mehrfach — «неоднократно», а разговор был один и короткий.","47":"Bevor — «прежде чем» (союз, глагол einreiche в конце). vor — предлог, ему нужно существительное: vor meiner Kündigung.","48":"dazu — sich entschließen zu → mich dazu entschlossen, … zu nutzen. damit к глаголу entschließen не подходит.","49":"Allerdings — «однако, правда»: срок увольнения знаю, но есть ещё отпуск. После allerdings — инверсия (habe ich).","50":"ob — косвенный вопрос «ли»: согласны ли вы. dass после wissen сообщает факт, а не задаёт вопрос.","51":"Sobald — «как только»: как только получу ответ, подам заявление. bevor здесь нелогично по порядку событий."},"extra":"Лишние: damit, dass, mehrfach, vor."},{"id":"s16t2","title":"Übung 16 · Teil 2","thema":"Angebot","type":"abc","head":"Angebot Arbeitskleidung","paras":["Sehr geehrter Herr Krause,","über Ihr Interesse an unserer Arbeitskleidung haben wir uns sehr gefreut. Bezug nehmend auf Ihre Anfrage vom 4. Februar unterbreiten wir Ihnen auf Grundlage unserer beiliegenden Verkaufs- und Lieferbedingungen gerne {52}:","<div class=\"shb-tw\"><table class=\"shb-t\"><tr><th>Artikel</th><th>Preis</th></tr><tr><td><b>Malerjacke „Pro“</b><br>weiß, sechs Taschen</td><td>49,90 €</td></tr><tr><td><b>Latzhose „Pro“</b><br>weiß, Knieschutztaschen</td><td>59,90 €</td></tr></table></div>","Größentabelle und Pflegehinweise finden Sie im beiliegenden Katalog. Der Kaufpreis ist ohne Abzug innerhalb von 30 Tagen nach Erhalt der Rechnung fällig. Alle Preise verstehen sich inklusive {53}. Bei Zahlung innerhalb von zehn Tagen gewähren wir 2 % Skonto.","Wir sind sicher, dass Sie mit der Qualität unserer Kleidung zufrieden sein werden, und versprechen Ihnen {54} innerhalb von fünf Werktagen nach Auftragseingang. Sollte Ihnen ein Artikel nicht passen, {55} wir selbstverständlich die Kosten der Rücksendung.","Über {56} würden wir uns sehr freuen. Für Rückfragen sind wir unter der Telefonnummer 07441 52380 jederzeit {57}.","Mit freundlichen Grüßen<br>i. A. Jana Seidel<br>Vertrieb"],"items":[{"n":52,"o":["die bestellte Ware","die offene Rechnung","das folgende Angebot"],"a":2,"t":"Nomen-Verb-Verbindung","w":"ein Angebot unterbreiten — «представить предложение»: устойчивое сочетание, а folgende указывает на список ниже. Заказа ещё нет (только Anfrage), счёта тоже."},{"n":53,"o":["der gesetzlichen Mehrwertsteuer","des möglichen Skontos","der späteren Rücksendung"],"a":0,"t":"Wortschatz","w":"inklusive der gesetzlichen Mehrwertsteuer — «с НДС», стандартная формула (inklusive + Gen.). Skonto дают только при ранней оплате, а возврат — отдельная тема."},{"n":54,"o":["eine baldige Bestellung","eine schnelle Lieferung","eine pünktliche Überweisung"],"a":1,"t":"Wortschatz","w":"eine schnelle Lieferung versprechen — продавец обещает поставку через 5 рабочих дней. Заказ и оплата — действия клиента, их продавец обещать не может."},{"n":55,"o":["übertragen","übernehmen","überziehen"],"a":1,"t":"Nomen-Verb-Verbindung","w":"die Kosten übernehmen — «взять расходы на себя». übertragen — «передать», überziehen — «превысить (лимит счёта)»."},{"n":56,"o":["die Erledigung Ihrer Reklamation","die Abwicklung Ihrer Kündigung","die Erteilung eines Auftrags"],"a":2,"t":"Nomen-Verb-Verbindung","w":"die Erteilung eines Auftrags — «выдача заказа» (einen Auftrag erteilen): фирма надеется на заказ. Рекламации и расторжения здесь нет."},{"n":57,"o":["erreichbar","erhältlich","zugänglich"],"a":0,"t":"Wortschatz","w":"erreichbar — «на связи, доступен (по телефону)»: так говорят о людях. erhältlich — «в продаже» (о товарах), zugänglich — «доступный» (о местах, информации)."}]},{"id":"s17t1","title":"Übung 17 · Teil 1","thema":"Bewerbung / Nachfrage","type":"bank","head":"Betreff: Meine Bewerbung vom 3. September","paras":["Sehr geehrte Damen und Herren,","am 3. September habe ich mich bei Ihnen um die Stelle als Elektroniker für Energie- und Gebäudetechnik beworben. Da ich bis heute {46} eine Eingangsbestätigung noch eine Antwort erhalten habe, möchte ich auf diesem Weg nachfragen, {47} meine Unterlagen bei Ihnen angekommen sind.","Sollten noch Unterlagen fehlen, lassen Sie es mich bitte wissen. Ich werde sie Ihnen {48} nach Erhalt Ihrer Nachricht zuschicken.","Auch {49} Sie meine Bewerbung noch nicht bearbeitet haben, würde ich mich über eine kurze Nachricht freuen, bis wann ich mit einer Entscheidung rechnen kann. In meiner jetzigen Firma werden {50} zurzeit die Monteure für ein großes Solarprojekt eingeteilt, das bis Ende des Jahres läuft. Eventuell könnte ich meinen Einsatz in diesem Projekt {51} einmal zurückstellen – in der Hoffnung, bald in Ihrem Unternehmen arbeiten zu können.","Vielen Dank für Ihre Bemühungen.","Mit freundlichen Grüßen<br>Taras Kovalenko"],"bank":[["a","deshalb"],["b","erst"],["c","nämlich"],["d","noch"],["e","ob"],["f","sobald"],["g","sofort"],["h","wann"],["i","weder"],["j","wenn"]],"key":{"46":"i","47":"e","48":"g","49":"j","50":"c","51":"b"},"cap":[],"topic":{"46":"Konnektor","47":"Konnektor","48":"Adverb","49":"Konnektor","50":"Adverb","51":"Adverb"},"why":{"46":"weder … noch — «ни … ни»: ни подтверждения, ни ответа. noch уже стоит в тексте, поэтому noch из банка — ловушка.","47":"ob — косвенный вопрос «ли»: дошли ли документы. wann предполагает, что они точно дошли, а этого автор как раз не знает.","48":"sofort — «сразу»: sofort nach Erhalt Ihrer Nachricht. sobald — союз, после него нужен глагол в конце.","49":"Auch wenn — «даже если»: даже если заявку ещё не рассмотрели. wann — вопросительное слово, «auch wann» по-немецки не бывает.","50":"nämlich — «дело в том, что»: объясняет причину. Стоит только в середине предложения (werden nämlich zurzeit …), никогда в начале.","51":"erst einmal — «пока что, для начала»: отложить участие в проекте на время. noch einmal — «ещё раз», а раньше ничего не откладывали."},"extra":"Лишние: deshalb, noch, sobald, wann."}];
